  it('requires an owner-preserving runtime carrier to erase structural rows', () => {
    const cases = [
      `interface Widget { value: number }
       export function erase(value: Readonly<Widget>): unknown { return value; }`,
      `interface Widget { value: number }
       function pass(value: unknown): unknown { return value; }
       export function erase(value: Readonly<Widget>): unknown { return pass(value); }`,
      `interface Widget { value: number }
       function pass(value: unknown): unknown { return value; }
       export function read(value: Readonly<Widget>, name: string): unknown {
         return (pass(value) as Record<string, unknown>)[name];
       }`,
      `interface Core { value: number }
       export function erase<Traits extends object>(value: Readonly<Core & NoInfer<Traits>>): unknown {
         return value;
       }`,
      `interface Node<Traits> { enabled: boolean; traits: Traits }
       type NodeAny = Readonly<Node<any>>;
       export function readNodeProperty(target: NodeAny, property: string): unknown {
         return (target as unknown as Readonly<Record<string, unknown>>)[property];
       }`,
    ];

    for (const [index, source] of cases.entries()) {
      const result = lower(`erased-structural-row-${index}.ts`, source);
      const failure = captureBackendEmissionFailure(() =>
        emitIrModuleCpp(result.module, { runtimeProfile: 'flight-cpp' }),
      );
      expect(failure.rule).toBe('cpp-erased-structural-row-construction-unrepresented');
      expect(failure.classification).toBe('target-runtime');
      expect(failure.message).toContain(
        'runtime contract needs a structural object alternative constructed from the row owner and native object, with the native type retained for checked recovery',
      );
      expect(failure.message).toContain('keep the value and API boundary in its nominal or structural type');
      expect(failure.message).toContain('using shared_object() would change identity or lose a widened owner');
      expect(failure.message).toContain('an unchecked cast would discard the evidence needed for checked recovery');
    }
  });

