    const skinning = captureBackendEmissionFailure(() => session.emitModule(modules[4]!));
    const typedSceneSkeleton = session.emitModule(modules[5]!)[0]!.contents;
    const typedSkinning = session.emitModule(modules[6]!)[0]!.contents;

