  it('converts a union holding a subset of the destination alternatives in every position', () => {
    const result = lower(
      'contextual-union-subset.ts',
      `interface Alpha { a: number }
       interface Beta { b: number }
       interface Gamma { c: number }
       interface Holder { slot: Alpha | Beta | Gamma }
       function take(_value: Alpha | Beta | Gamma): number { return 1; }
       export function pass(value: Alpha | Beta): number { return take(value); }
       export function read(value: Alpha | Beta): Alpha | Beta | Gamma { return value; }
       export function nullable(
         value: (Alpha | Beta) | undefined,
       ): (Alpha | Beta | Gamma) | undefined { return value; }
       export function put(holder: Holder, value: Alpha | Beta): void { holder.slot = value; }`,
    );
    const contents = emitIrModuleCpp(result.module, { runtimeProfile: 'flight-cpp' }).contents;

    // Every alternative the value can hold is one the destination stores at the same C++ type, so the
    // conversion is a checked rebuild: `get_if` per held alternative, copied into the destination carrier,
    // and an alternative the value cannot hold gets no branch. The source language accepts the conversion,
    // so it is the target's to make rather than the source's to restate.
    expect(contents).toContain('([&]() -> std::variant<flight::Ref<Alpha>, flight::Ref<Gamma>, flight::Ref<Beta>>');
    expect(contents).toContain('std::get_if<flight::Ref<Alpha>>(&converted_union)');
    expect(contents).toContain('std::get_if<flight::Ref<Beta>>(&converted_union)');
    expect(contents).not.toContain('std::get_if<flight::Ref<Gamma>>');
    expect(contents).toContain('(holder->slot = ([&]() -> std::variant<flight::Ref<Alpha>');
    expect(contents).not.toContain('std::optional<std::optional<');
    expect(contents).not.toContain('cpp-contextual-union-inequivalent');
  });

  it('preserves recursive union owners after a unique-symbol guard', () => {
    const result = lower(
      'recursive-union-symbol-guard.ts',
      `type Value = null | boolean | number | string | Value[] | Mapping;
       interface Mapping { [key: string]: Value }
       const FAILURE = Symbol('failure');
       type ParseValue = Value | typeof FAILURE;
       function take(value: Value): Value { return value; }
       export function parse(mapping: Mapping, sequence: Value[], key: string, value: ParseValue): Value | null {
         if (value === FAILURE) return null;
         mapping[key] = value;
         sequence.push(value);
         return take(value);
       }`,
    );
    const parse = result.module.declarations.find(
      (declaration) => declaration.kind === 'function' && declaration.binding.name === 'parse',
    );
    const guard = parse?.kind === 'function' ? parse.body[0] : undefined;
    expect(
      guard?.kind === 'if' && guard.condition.kind === 'binary' ? guard.condition.semantics : undefined,
    ).toMatchObject({ unionMemberTest: { binding: { name: 'value' }, whenResult: true } });
    const assignment = parse?.kind === 'function' ? parse.body[1] : undefined;
    const assignedValue =
      assignment?.kind === 'expression' && assignment.expression.kind === 'assignment'
        ? assignment.expression.right
        : undefined;

    expect(assignedValue).toMatchObject({
      kind: 'identifier',
      narrowedType: { kind: 'union' },
    });

    const contents = emitIrModuleCpp(result.module, { runtimeProfile: 'flight-cpp' }).contents;

    expect(result.diagnostics).toEqual([]);
    expect(contents).toContain('mapping.set(key,');
    expect(contents).toContain('sequence.push(');
    expect(contents).toContain('return take(');
    expect(contents).toContain('std::get_if<flight::Array<Value>>');
    expect(contents).toContain('std::get_if<flight::Record<flight::String, Value>>');
    expect(contents).not.toContain('flight::make_ref');
    expect(contents).not.toContain('static_cast');
    expect(contents).not.toContain('cpp-contextual-union-inequivalent');
  });

