  it('adapts a contextual callable that ignores trailing parameters and one that accepts a wider parameter', () => {
    const result = lower(
      'contextual-callable-trailing-parameters.ts',
      `type Factory = (value?: number) => string;
       function createFactory(): () => string { return (): string => 'created'; }
       export function factory(): Factory | undefined { return createFactory(); }`,
    );

    expect(result.diagnostics).toEqual([]);
    const emitted = emitIrModuleCpp(result.module, { runtimeProfile: 'flight-cpp' }).contents;
    expect(emitted).toContain(
      'std::optional<std::function<flight::String(std::optional<double>)>>{[contextual_callable = create_factory()](std::optional<double> contextual_callable_argument0) -> flight::String { return contextual_callable(); }}',
    );
    expect(emitted.match(/contextual_callable = create_factory\(\)/gu)).toHaveLength(1);

    // The other parameter mismatch the source language allows is a value that accepts a WIDER payload
    // than the destination supplies, and it is the mirror the adapter already carries: the destination's
    // signature is the only caller, so the argument it names is one the value's variant takes, and the
    // variant constructs itself from it. This case was previously refused because the matcher compared
    // payload spellings, which cannot see that a member of a union is a value the union stores.
    const widened = emitIrModuleCpp(
      lower(
        'contextual-callable-wider-parameter.ts',
        `type NumberConsumer = (value: number) => string;
         function consumeNumberOrString(value: number | string): string { return String(value); }
         export function consumer(): NumberConsumer | undefined { return consumeNumberOrString; }`,
      ).module,
      { runtimeProfile: 'flight-cpp' },
    ).contents;
    expect(widened).toContain(
      'std::optional<std::function<flight::String(double)>>{[](double contextual_callable_argument0) -> flight::String { return consume_number_or_string(contextual_callable_argument0); }}',
    );

    // A concrete result is also callable through a signature that admits that exact result or absence.
    // The target std::function performs the value-to-optional construction; no result cast or object
    // materialization is involved.
    const widenedReturn = emitIrModuleCpp(
      lower(
        'contextual-callable-wider-return.ts',
        `class Texture2D { readonly width = 1; }
         type Resolver = (id: number, repeat: boolean, smooth: boolean) => Texture2D | null;
         function acquire(id: number, repeat: boolean, smooth: boolean): Texture2D {
           void id; void repeat; void smooth;
           return new Texture2D();
         }
         export function resolver(): Resolver | null {
           return (id, repeat, smooth) => acquire(id, repeat, smooth);
         }`,
      ).module,
      { runtimeProfile: 'flight-cpp' },
    ).contents;
    expect(widenedReturn).toContain(
      'std::optional<std::function<std::optional<flight::Ref<Texture2D>>(double, bool, bool)>>{',
    );
  });

