  it('scopes an imported enum member and refuses an array read out of an erased value', () => {
    // Two scene2d-canvas failures, one compiler-side and one at the runtime's boundary.
    //
    // An enum member is a scoped name: the source writes `Rotation.member` and C++ needs `Rotation::member`.
    // A local enum already reaches that spelling, but an imported one arrives as a value-space binding and
    // took the ordinary member operator, emitting a dot on a type — which is not an expression.
    const types = lowerPackage(
      '@flighthq/types',
      'rotation.ts',
      "export enum TextureAtlasRotation { clockwise90 = 'cw', counterclockwise90 = 'ccw' }",
    ).module;
    const consumer = lowerPackage(
      '@flighthq/scene2d-canvas',
      'canvasAtlasRegion.ts',
      `import { TextureAtlasRotation } from '@flighthq/types';
       export function pick(): string { return TextureAtlasRotation.counterclockwise90; }`,
    ).module;
    const emitted = createCppCompilerBackend().createEmissionSession!({
      moduleResolution: {
        edges: [{ specifier: '@flighthq/types', target: { packageName: types.packageName, source: types.source } }],
        schema: 'flight-compiler-module-resolution/1',
      },
      modules: [consumer, types],
      options: { runtimeProfile: 'flight-cpp' },
    }).emitModule(consumer)[0]!.contents;
    expect(emitted).toContain('flighthq_types::TextureAtlasRotation::Counterclockwise90');
    expect(emitted).not.toContain('TextureAtlasRotation.counterclockwise90');

    const rotation = lowerPackage(
      '@flighthq/types',
      'rotation.ts',
      "export enum TextureAtlasRotation { clockwise90 = 'cw', counterclockwise90 = 'ccw' }",
    ).module;
    const contract = lowerPackage('@flighthq/types', 'contract.ts', "export * from './rotation';").module;
    const barrelConsumer = lowerPackage(
      '@flighthq/scene2d-canvas',
      'barrelCanvasAtlasRegion.ts',
      `import { TextureAtlasRotation } from '@flighthq/types/contract';
       export function pick(): string { return TextureAtlasRotation.counterclockwise90; }`,
    ).module;
    const barrelEmitted = createCppCompilerBackend().createEmissionSession!({
      moduleResolution: {
        edges: [
          {
            specifier: '@flighthq/types/contract',
            target: { packageName: contract.packageName, source: contract.source },
          },
          { specifier: './rotation', target: { packageName: rotation.packageName, source: rotation.source } },
        ],
        schema: 'flight-compiler-module-resolution/1',
      },
      modules: [barrelConsumer, contract, rotation],
      options: { runtimeProfile: 'flight-cpp' },
    }).emitModule(barrelConsumer)[0]!.contents;
    expect(barrelEmitted).toContain('flighthq_types::TextureAtlasRotation::Counterclockwise90');

    // The second failure is the runtime's boundary, and the compiler's part of it is to say so instead of
    // emitting a cast to a conversion that does not exist: an element read out of an `any[]` is the erased
    // value, and `flight::Array` is not something `Any` can carry. The primitives it CAN carry still read
    // out through their own accessors.
    const refusal = (source: string): string | undefined => {
      try {
        emitIrModuleCpp(lower('erased-array.ts', source).module, { runtimeProfile: 'flight-cpp' });
        return undefined;
      } catch (error) {
        return isBackendEmissionFailure(error) ? error.rule : undefined;
      }
    };
    expect(
      refusal(`export function path(commands: any[], i: number): number[] { return commands[i + 2] as number[]; }`),
    ).toBe('cpp-erased-value-assertion-unrepresented');
    expect(
      emitIrModuleCpp(
        lower('erased-number.ts', `export function size(value: unknown): number { return value as number; }`).module,
        { runtimeProfile: 'flight-cpp' },
      ).contents,
    ).toContain('.as_number()');
  });

  it('preserves an exact array carrier across erased assertion syntax and classifies the unrepresented cases', () => {
    const exact = emitIrModuleCpp(
      lower(
        'erased-array-exact-source.ts',
        `export function read(values: number[]): number[] {
           return values as unknown as number[];
         }`,
      ).module,
      { runtimeProfile: 'flight-cpp' },
    ).contents;

    // The intermediate `unknown` is assertion syntax, not storage. Exact evidence on its source proves the
    // same Array<double> carrier reaches the result, so emission keeps that identity and constructs nothing.
    expect(exact).toContain('return values;');
    expect(exact).not.toContain('flight::Any');
    expect(exact).not.toContain('static_cast');

    const incompatible = captureBackendEmissionFailure(() =>
      emitIrModuleCpp(
        lower(
          'erased-array-incompatible-source.ts',
          `export function read(values: number[]): string[] {
             return values as unknown as string[];
           }`,
        ).module,
        { runtimeProfile: 'flight-cpp' },
      ),
    );
    expect(incompatible).toMatchObject({
      classification: 'source-portability',
      rule: 'cpp-erased-value-assertion-unrepresented',
    });
    expect(incompatible.message).toContain('flight::Array<double>');
    expect(incompatible.message).toContain('flight::Array<flight::String>');
    expect(incompatible.message).toContain('explicitly convert its elements');
    expect(incompatible.message).toContain('will not reinterpret the source carrier, cast it, or materialize');

    const refusal = (file: string, source: string) =>
      captureBackendEmissionFailure(() =>
        emitIrModuleCpp(lower(file, source).module, { runtimeProfile: 'flight-cpp' }),
      );
    const unityParse = refusal(
      'unity-parse-erased-array.ts',
      `function readEmission(obj: unknown): void {
         if (obj == null || typeof obj !== 'object') return;
         const fields = obj as Record<string, unknown>;
         const bursts = Array.isArray(fields.bursts)
           ? (fields.bursts as Record<string, unknown>[]).map((burst) => burst)
           : [];
         void bursts;
       }
       export function parse(value: unknown): void { readEmission(value); }`,
    );
    const equalsSnapshot = refusal(
      'equals-snapshot-erased-array.ts',
      `export function equal(left: unknown, right: unknown): boolean {
         if (!Array.isArray(left) || !Array.isArray(right)) return false;
         const leftArray = left as unknown[];
         const rightArray = right as unknown[];
         return leftArray.length === rightArray.length;
       }`,
    );

    for (const failure of [unityParse, equalsSnapshot]) {
      expect(failure).toMatchObject({
        classification: 'target-runtime',
        rule: 'cpp-erased-value-assertion-unrepresented',
      });
      expect(failure.message).toContain('flight::Any has no array alternative or checked exact-array extraction');
      expect(failure.message).toContain('Keep the value in its exact array type before the erased boundary');
      expect(failure.message).toContain('will not reinterpret the erased value, cast it, or materialize');
    }
    expect(unityParse.message).toContain('flight::Array<flight::Record<flight::String, flight::Any>>');
    expect(equalsSnapshot.message).toContain('flight::Array<flight::Any>');
  });

