  it('passes an exact owner into a readonly structural view through the structural-ref lane', () => {
    // The bitmapfont subcase: a page of `readonly TextureAtlas[]` is handed to a parameter typed
    // `Readonly<TextureAtlas>`. That is the SAME referent under a readonly view, so the conversion is the
    // runtime's own two steps — a structural ref constructed from the native owner and a cast between
    // structural refs — and no alias primitive is missing. Kept as a control because the emission is a
    // two-step spelling a future change could collapse into a copy without any test noticing.
    const result = lower(
      'exact-owner-view.ts',
      `export interface TextureAtlas { readonly name: string; readonly regions: readonly number[] }
       export function atlasByteSize(atlas: Readonly<TextureAtlas>): number { return atlas.regions.length; }
       export function summarize(pages: readonly TextureAtlas[]): number {
         let total = 0;
         for (const page of pages) total += atlasByteSize(page);
         return total;
       }`,
    );
    const emitted = emitIrModuleCpp(result.module, { runtimeProfile: 'flight-cpp' }).contents;

    expect(result.diagnostics).toEqual([]);
    expect(emitted).toContain(
      'flight::structural_ref_cast<flight::StructuralRef<flight::RowReadonly<flight::RowOf<flight::Ref<TextureAtlas>>>>>(flight::StructuralRef<flight::RowWritable<flight::RowOf<flight::Ref<TextureAtlas>>>>(page))',
    );
    // The owner is viewed, never copied: no `make_ref`, no `make_structural_ref`, no property by property
    // rebuild of the page.
    expect(emitted).not.toContain('flight::make_ref<TextureAtlas>');
    expect(emitted).not.toContain(
      'flight::make_structural_ref<flight::StructuralRef<flight::RowReadonly<flight::RowOf<flight::Ref<TextureAtlas>>>>',
    );
  });

  it('defaults an optional call result instead of dropping the fallback as a tautology', () => {
    // `f?.()` is `undefined` when the callee is missing, whatever the callee's return says, so the `??`
    // fallback is reachable and must be emitted. The call's type evidence reports only the callee's return,
    // so a rule that keys on the declared type alone reads the coalesce as a tautology and drops the
    // default — leaving `optional<double>` where the source has a `number`, which no ternary branch can
    // meet. The positive case pins the default; the negative case pins that the tautology rule still
    // applies to a call that genuinely cannot be absent.
    const optional = emitIrModuleCpp(
      lower(
        'optional-call-default.ts',
        `export interface HostVideoCapability { readonly getDuration?: (element: number) => number }
         export function videoDuration(hostVideo: HostVideoCapability, element: number | null): number {
           return element !== null ? (hostVideo.getDuration?.(element) ?? 0) : 0;
         }`,
      ).module,
      { runtimeProfile: 'flight-cpp' },
    ).contents;
    expect(optional).toContain('}()).value_or(0.0) : 0.0');

    const required = emitIrModuleCpp(
      lower(
        'required-call-default.ts',
        `function measure(element: number): number { return element; }
         export function size(element: number | null): number {
           return element !== null ? (measure(element) ?? 0) : 0;
         }`,
      ).module,
      { runtimeProfile: 'flight-cpp' },
    ).contents;
    // A call that cannot be absent answers the test at compile time, so the fallback really is
    // unreachable and no default is emitted.
    expect(required).toContain('measure(element.value())');
    expect(required).not.toContain('value_or(0.0)');
  });

  it('types an Object.entries value from the record it enumerates, and only as far as the record proves', () => {
    // `net/netForm.ts` hands an entry value to a `string` parameter. The runtime's `object_entries` returns an
    // erased value, so the domain has to come from the record the source enumerated — and only from what that
    // record proves. A `Record<string, string>` proves string; anything else must keep its own domain, because
    // reading every entry value as a string would silently stringify numbers, booleans and records alike.
    const stringRecord = emitIrModuleCpp(
      lower(
        'entries-string.ts',
        `function encodeFormComponent(value: string): string { return value; }
         export function formatNetFormBody(fields: Readonly<Record<string, string>>): string {
           return Object.entries(fields)
             .map(([key, value]) => \`\${encodeFormComponent(key)}=\${encodeFormComponent(value)}\`)
             .join('&');
         }`,
      ).module,
      { runtimeProfile: 'flight-cpp' },
    ).contents;
    expect(stringRecord).toContain('std::tuple<flight::String, flight::String> parameter_pattern_value');
    expect(stringRecord).toContain('flight::String value;');
    expect(stringRecord).not.toContain('flight::Any');

    // The non-string side: the entry value keeps its own domain and is never stringified.
    const numberRecord = emitIrModuleCpp(
      lower(
        'entries-number.ts',
        `export function total(fields: Readonly<Record<string, number>>): number {
           let sum = 0;
           for (const [, value] of Object.entries(fields)) sum += value;
           return sum;
         }`,
      ).module,
      { runtimeProfile: 'flight-cpp' },
    ).contents;
    expect(numberRecord).toContain('flight::Record<flight::String, double> fields');
    expect(numberRecord).toContain('auto value = std::get<1>(array_pattern_value);');
    expect(numberRecord).not.toContain('flight::to_string(value)');
  });

  it('stamps a signal call through a closed-key selection with the callable it selected', () => {
    // `media/audioChannel.ts` selects a signal by name and emits it. The selection's element type is the
    // union of the members the keys name, and that evidence is what lets the callee's type parameter be
    // deduced — so the emitted call carries the explicit template argument. It has to, because the runtime's
    // `flight::Ref` is a `std::conditional_t` alias and therefore a non-deduced context: a call that leans on
    // deduction cannot name `T` at all, whatever its arity. Arity is taken from the selected callable, and
    // nothing is passed that the source did not pass.
    const zeroArity = emitIrModuleCpp(
      lower(
        'signal-selection-zero.ts',
        `export interface Signal<T> { readonly id: number }
         export interface ChannelSignals { readonly onComplete: Signal<() => void>; readonly onLoop: Signal<() => void> }
         export function emitSignal<T>(signal: Signal<T>): void { void signal.id; }
         export function emitChannelSignal(signals: ChannelSignals, name: 'onComplete' | 'onLoop'): void {
           emitSignal(signals[name]);
         }`,
      ).module,
      { runtimeProfile: 'flight-cpp' },
    ).contents;
    expect(zeroArity).toContain(
      'emit_signal<std::function<void()>>(([&]() -> flight::Ref<Signal<std::function<void()>>>',
    );

    // The arity-negative side: a callable that takes a parameter keeps that parameter, and the call gains no
    // argument the source did not write.
    const oneArity = emitIrModuleCpp(
      lower(
        'signal-selection-one.ts',
        `export interface Signal<T> { readonly id: number }
         export interface ChannelSignals { readonly onProgress: Signal<(value: number) => void>; readonly onDone: Signal<(value: number) => void> }
         export function emitSignal<T>(signal: Signal<T>, value: number): void { void signal.id; void value; }
         export function emitProgress(signals: ChannelSignals, name: 'onProgress' | 'onDone', value: number): void {
           emitSignal(signals[name], value);
         }`,
      ).module,
      { runtimeProfile: 'flight-cpp' },
    ).contents;
    expect(oneArity).toContain(
      'emit_signal<std::function<void(double)>>(([&]() -> flight::Ref<Signal<std::function<void(double)>>>',
    );
    expect(oneArity).not.toContain('flight::Any');
  });

  it('folds a variadic Math.hypot onto the arities the C++ overloads answer', () => {
    // `Math.hypot` takes any number of arguments; `std::hypot` answers two and three. Four arguments used to
    // be passed straight through as `std::hypot(x, y, z, w)`, which names no overload — the animation blend
    // header's own failure. A left fold over the supported forms is exact, and the arities the overloads do
    // answer must keep their direct spelling rather than growing a fold they do not need.
    const emitted = emitIrModuleCpp(
      lower(
        'hypot-arities.ts',
        `export function four(x: number, y: number, z: number, w: number): number { return Math.hypot(x, y, z, w); }
         export function five(x: number, y: number, z: number, w: number, v: number): number { return Math.hypot(x, y, z, w, v); }
         export function three(x: number, y: number, z: number): number { return Math.hypot(x, y, z); }
         export function two(x: number, y: number): number { return Math.hypot(x, y); }
         export function one(x: number): number { return Math.hypot(x); }
         export function none(): number { return Math.hypot(); }`,
      ).module,
      { runtimeProfile: 'flight-cpp' },
    ).contents;

    // Four and five fold onto the three-argument form; no call is left with an arity no overload answers.
    expect(emitted).toContain('std::hypot(std::hypot(x, y, z), w)');
    expect(emitted).toContain('std::hypot(std::hypot(std::hypot(x, y, z), w), v)');
    expect(emitted).not.toMatch(/std::hypot\([^()]*,[^()]*,[^()]*,[^()]*\)/u);
    // Two and three are the overloads themselves.
    expect(emitted).toContain('return std::hypot(x, y);');
    expect(emitted).toContain('return std::hypot(x, y, z);');
    // One is the absolute value and none is the source's own zero, which no std::hypot overload answers.
    expect(emitted).toContain('return std::abs(x);');
    expect(emitted).toContain('return 0.0;');
  });

  it('materializes an object literal passed to a callable rather than sending a brace list', () => {
    // The shape `@flighthq/socket` uses: a module-level optional guard invoked with an object literal, and a
    // signal helper that forwards a rest pack. A brace-enclosed list cannot convert to a `Ref<T>` parameter,
    // and cannot be deduced into a variadic pack at all, so either one reaching the emitted call is a compile
    // error — `no match for call to 'std::function<void(Ref<...>)>'`. The literal is built at the call site
    // instead, at whatever the parameter's type asks for.
    const guard = emitIrModuleCpp(
      lower(
        'guard-notice.ts',
        `export interface SocketGuardNotice { readonly operation: string; readonly socket: object }
         export type SocketGuard = (notice: Readonly<SocketGuardNotice>) => void;
         let _guard: SocketGuard | null = null;
         export function setSocketGuard(guard: SocketGuard | null): void { _guard = guard; }
         export function closeSocket(): void { _guard?.({ operation: 'closeSocket', socket: {} }); }`,
      ).module,
      { runtimeProfile: 'flight-cpp' },
    ).contents;
    expect(guard).toContain('optional_chain_receiver.value()(flight::make_structural_ref<');
    expect(guard).not.toMatch(/value\(\)\(\{/u);

    // The signal helper's own signature, as `@flighthq/signals` writes it: a rest pack of the callable's
    // parameters. The literal is materialized before it is forwarded, not passed as a brace list into the pack.
    const signal = emitIrModuleCpp(
      lower(
        'signal-guard.ts',
        `export interface Signal<T> { readonly id: number }
         export function emitSignal<T extends (...args: never[]) => void>(signal: Signal<T>, ...args: Parameters<T>): void { void signal; }
         export interface SocketGuardNotice { readonly operation: string; readonly socket: object }
         export function warn(signal: Signal<(notice: Readonly<SocketGuardNotice>) => void>): void {
           emitSignal(signal, { operation: 'closeSocket', socket: {} });
         }`,
      ).module,
      { runtimeProfile: 'flight-cpp' },
    ).contents;
    expect(signal).toContain('emit_signal<std::function<void(flight::StructuralRef<');
    expect(signal).not.toMatch(/emit_signal<[^>]*>\(signal, \{/u);
    expect(signal).toContain('flight::make_ref<');
  });

  it('forwards a rest parameter pack as a terminal call spread and refuses every other use of it', () => {
    // `@flighthq/signals/src/emitter.ts` is `(signal.emit as (...a: any[]) => void)(...args)` — a rest
    // parameter pack forwarded as the terminal argument of a call. That is the one shape the pack has a
    // sound reading for, and it emits as a real pack expansion rather than an array.
    const HEADER = `export interface Signal<T> { readonly id: number; readonly emit: (...arguments_: unknown[]) => void }
`;
    const emitted = (body: string): string =>
      emitIrModuleCpp(lower('emitter.ts', `${HEADER}${body}`).module, { runtimeProfile: 'flight-cpp' }).contents;
    expect(
      emitted(
        `export function emitSignal<T extends (...args: any[]) => void>(signal: Signal<T>, ...args: Parameters<T>): void {
           (signal.emit as (...a: any[]) => void)(...args);
         }`,
      ),
    ).toContain('signal->emit(std::forward<ArgsPack>(args)...)');

    // The negative side. Every other use of the pack is refused rather than approximated into an array, and
    // the two policies share one rule tag, so the message is what separates them.
    const refusal = (body: string): string | undefined => {
      try {
        emitted(body);
        return undefined;
      } catch (error) {
        return isBackendEmissionFailure(error) ? error.message : undefined;
      }
    };
    expect(
      refusal(
        `export function use<T extends (...args: any[]) => void>(signal: Signal<T>, ...args: Parameters<T>): void { void args; }`,
      ),
    ).toContain('may only be used as a terminal call spread');
    expect(
      refusal(
        `function pair(a: number, b: number): void { void a; void b; }
         export function use<T extends (...args: any[]) => void>(signal: Signal<T>, ...args: Parameters<T>): void { pair(...args, 1); }`,
      ),
    ).toContain('require terminal call expansion');
  });

  it('declares an intersection alternative its own members rather than inheriting them', () => {
    // `CollisionBuiltInShape2D` is a union of intersections — `CollisionObb2D & { kind: 'obb' }` and friends —
    // and a literal for one alternative becomes an anonymous struct. C++ designated initializers may name only
    // DIRECT non-static data members, so a struct that inherited `CollisionObb2D` and then designated `.x`
    // would be rejected: "no non-static data member named 'x'". The alternative declares everything the
    // literal writes, and the construction designates exactly those.
    const types = lowerPackage(
      '@flighthq/types',
      'collision.ts',
      `export interface CollisionObb2D { readonly x: number; readonly y: number; readonly halfW: number; readonly halfH: number; readonly rotation: number }
       export interface CollisionCapsule2D { readonly ax: number; readonly ay: number }
       export type CollisionBuiltInShape2D =
         | (CollisionObb2D & { readonly kind: 'obb' })
         | (CollisionCapsule2D & { readonly kind: 'capsule' });`,
    ).module;
    const consumer = lowerPackage(
      '@flighthq/collision',
      'raycastCollisionShape2D.ts',
      `import type { CollisionBuiltInShape2D } from '@flighthq/types';
       const probe: CollisionBuiltInShape2D = { kind: 'obb', x: 0, y: 0, halfW: 0, halfH: 0, rotation: 0 };
       export function get(): CollisionBuiltInShape2D { return probe; }`,
    ).module;
    const session = createCppCompilerBackend().createEmissionSession!({
      moduleResolution: {
        edges: [{ specifier: '@flighthq/types', target: { packageName: types.packageName, source: types.source } }],
        schema: 'flight-compiler-module-resolution/1',
      },
      modules: [consumer, types],
      options: { runtimeProfile: 'flight-cpp' },
    });

    // The alternative is a standalone reference-enabled struct, not a subtype of the named interface.
    const declared = session.emitModule(types)[0]!.contents;
    expect(declared).toContain('struct x_y_half_w_half_h_rotation_kind_');
    expect(declared).not.toMatch(/struct x_y_half_w_half_h_rotation_kind_\w* : public flighthq_types::CollisionObb2D/u);
    expect(declared).toMatch(
      /struct x_y_half_w_half_h_rotation_kind_\w* : public flight::ReferenceEnabled \{\s*double x;/u,
    );

    // And the construction designates those members, which is what the direct declaration makes legal.
    expect(session.emitModule(consumer)[0]!.contents).toMatch(
      /x_y_half_w_half_h_rotation_kind_\w*\{\.x = object_member_x, \.y = object_member_y/u,
    );
  });

  it('initializes an inherited base member by assignment rather than by designation', () => {
    // A nominal intersection written out where it stands, over an IMPORTED interface base. Its implementation
    // INHERITS that base and declares only what the base does not provide, so a designated initializer naming
    // `x` names a member the struct does not have and g++ says so: "no non-static data member named 'x'". C++
    // will not let a base clause sit beside designated member clauses either — a list must be all designated
    // or none — so the inherited members are assigned onto the constructed value instead.
    //
    // This is the control for that rule. A selection that denotes this same arm — `Extract<CollisionBuiltInShape2D,
    // { kind: 'obb' }>` — no longer reaches this lane: it is named as the arm its union declares, so a literal of
    // it initializes that flat record rather than a second nominal implementation. Kept distinct on purpose,
    // because the two are different questions: what an imported base costs an implementation here, and which
    // declaration a selection denotes.
    const plan: CompilerModuleResolutionPlan = {
      edges: [
        {
          importer: undefined as never,
          specifier: '@flighthq/types',
          target: { packageName: '@flighthq/types', source: 'packages/types/src/collision.ts' },
        },
      ],
      schema: 'flight-compiler-module-resolution/1',
    };
    // Lowered together and with the resolution plan: the import is what makes the base an imported binding,
    // and an unbound one refuses before any of this reaches the emitter.
    const [types, consumer] = lowerTypeScriptSources(
      [
        {
          packageName: '@flighthq/types',
          sourceFile: ts.createSourceFile(
            '/flight/packages/types/src/collision.ts',
            `export interface CollisionObb2D { readonly x: number; readonly y: number; readonly halfW: number; readonly halfH: number; readonly rotation: number }
             export interface CollisionCapsule2D { readonly ax: number; readonly ay: number }
             export type CollisionBuiltInShape2D =
               | (CollisionObb2D & { readonly kind: 'obb' })
               | (CollisionCapsule2D & { readonly kind: 'capsule' });`,
            ts.ScriptTarget.Latest,
            true,
          ),
          upstreamDirectory: '/flight',
        },
        {
          packageName: '@flighthq/collision',
          sourceFile: ts.createSourceFile(
            '/flight/packages/collision/src/raycastCollisionShape2D.ts',
            `import type { CollisionObb2D } from '@flighthq/types';
             const probe: CollisionObb2D & { kind: 'obb' } = { kind: 'obb', x: 0, y: 0, halfW: 0, halfH: 0, rotation: 0 };
             export function get(): number { return probe.x; }`,
            ts.ScriptTarget.Latest,
            true,
          ),
          upstreamDirectory: '/flight',
        },
      ],
      plan,
    );
    const session = createCppCompilerBackend().createEmissionSession!({
      moduleResolution: plan,
      modules: [consumer!.module, types!.module],
      options: { runtimeProfile: 'flight-cpp' },
    });
    const emitted = session.emitModule(consumer!.module)[0]!.contents;

    // The base is inherited, which is what makes its members indirect.
    expect(emitted).toMatch(/struct x_y_half_w_half_h_rotation_kind_\w* : public flighthq_types::CollisionObb2D/u);
    // The initializer names only the struct's own member ...
    expect(emitted).toMatch(/x_y_half_w_half_h_rotation_kind_\w*\{\.kind = object_member_kind\}/u);
    expect(emitted).not.toMatch(/x_y_half_w_half_h_rotation_kind_\w*\{\.x = /u);
    // ... and all five inherited members are assigned onto the constructed value.
    for (const member of ['x', 'y', 'half_w', 'half_h', 'rotation']) {
      expect(emitted).toContain(`->${member} = object_member_`);
    }

    // The negative side: a base declared in the SAME module is not an import, so the implementation does not
    // inherit it and declares every member — and a designated initializer may name all of them.
    const local = emitIrModuleCpp(
      lower(
        'local-base.ts',
        `export interface CollisionObb2D { readonly x: number; readonly y: number }
         const probe: CollisionObb2D & { readonly kind: 'obb' } = { kind: 'obb', x: 0, y: 0 };
         export function get(): number { return probe.x; }`,
      ).module,
      { runtimeProfile: 'flight-cpp' },
    ).contents;
    expect(local).toMatch(/struct x_y_kind_\w* : public flight::ReferenceEnabled/u);
    expect(local).toMatch(/x_y_kind_\w*\{\.x = object_member_x/u);
  });

