  it('refuses an Extract that reached emission unresolved', () => {
    const result = lower(
      'cube-texture-open.ts',
      `interface Texture2D { readonly dimension: '2d'; width: number; }
       export type CubeTexture<Type extends Texture2D> = Extract<Type, { dimension: 'cube' }>;`,
    );
    const failure = captureBackendEmissionFailure(() =>
      emitIrModuleCpp(result.module, { runtimeProfile: 'flight-cpp' }),
    );

    // An open `Extract` cannot be computed, and writing the name out would produce a header that fails
    // wherever it is included -- `Extract` is not a C++ type and the target reports it far from the
    // declaration that used it. The refusal names the utility instead, which is the whole difference
    // between a diagnostic a reader can act on and a name that escapes.
    expect(failure.rule).toBe('cpp-typescript-utility-unexpanded:Extract');
    expect(failure.classification).toBe('compiler-restriction');
    expect(failure.message).toContain('Extract was not resolved before emission and has no C++ lowering');

    const unresolved = lower(
      'cube-texture-unresolved.ts',
      `import type { Texture } from '@flighthq/external';
       export type CubeTexture = Extract<Texture, { dimension: 'cube' }>;`,
    );
    const unresolvedFailure = captureBackendEmissionFailure(() =>
      emitIrModuleCpp(unresolved.module, { runtimeProfile: 'flight-cpp' }),
    );
    expect(unresolvedFailure.rule).toBe('cpp-typescript-utility-unexpanded:Extract');

    const indeterminate = structuredClone(lower('indeterminate-extract.ts', 'export type Result = string;').module);
    const alias = indeterminate.declarations.find((declaration) => declaration.kind === 'typeAlias');
    if (alias?.kind !== 'typeAlias') throw new TypeError('expected Result type alias');
    (alias as { type: IrType }).type = {
      kind: 'named',
      reference: { kind: 'ambient', name: 'Extract' },
      typeArguments: [
        {
          kind: 'object',
          properties: [
            {
              name: 'dimension',
              optional: false,
              readonly: true,
              type: { kind: 'unknown', source: 'unknown' },
            },
          ],
        },
        {
          kind: 'object',
          properties: [
            {
              name: 'dimension',
              optional: false,
              readonly: false,
              type: { kind: 'literal', value: 'cube' },
            },
          ],
        },
      ],
    };
    const indeterminateFailure = captureBackendEmissionFailure(() =>
      emitIrModuleCpp(indeterminate, { runtimeProfile: 'flight-cpp' }),
    );
    expect(indeterminateFailure.rule).toBe('cpp-typescript-utility-unexpanded:Extract');
  });

  it('attributes dependent discriminant Extract over complete arms to the source boundary', () => {
    const result = lower(
      'dependent-discriminant-extract.ts',
      `interface StateBase { disposed: boolean; }
       interface InputState extends StateBase {
         kind: 'input';
         messageSubscriptions: Set<string>;
         operations: (message: string) => void;
       }
       interface OutputState extends StateBase {
         kind: 'output';
         operations: (message: number) => void;
       }
       type State = InputState | OutputState;
       export function createState<
         Kind extends State['kind'],
         Operations extends State['operations'],
       >(kind: Kind, operations: Operations) {
         return { disposed: false, kind, operations } as Extract<State, { kind: Kind }>;
       }`,
    );
    const failure = captureBackendEmissionFailure(() =>
      emitIrModuleCpp(result.module, { runtimeProfile: 'flight-cpp' }),
    );

    // Both literal tags lower to the same C++ string type, so Kind cannot choose a return carrier. The
    // input value also becomes a complete arm only after its caller supplies messageSubscriptions. A
    // variant return would change that asserted boundary, while a row replacement would copy the
    // callable property. The source must therefore construct each complete arm explicitly.
    expect(failure.rule).toBe('cpp-extract-dependent-discriminant-unrepresented');
    expect(failure.classification).toBe('source-portability');
    expect(failure.message).toContain('dependent discriminant Kind');
    expect(failure.message).toContain('property kind admits "input", "output"');
    expect(failure.message).toContain('same C++ string carrier');
    expect(failure.message).toContain('one complete declared union arm');
    expect(failure.message).toContain('split the generic declaration by arm');
    expect(failure.message).toContain('will not choose an arm with an unchecked cast');
    expect(failure.message).toContain('materialize a replacement structural row');
  });

  it('resolves a conditional alias reference whose check names a parameter inside an indexed access', () => {
    const sourceFile = ts.createSourceFile(
      '/flight/packages/types/src/createTextureOptions.ts',
      `export interface Texture2D { dimension: '2d'; width: number; height: number; }
       export interface Texture3D { dimension: '3d'; depth: number; }
       export type TextureLike = Texture2D | Texture3D;
       export interface ImageResourceReference { url: string; }
       type CreateTextureVariantOptions<Type extends TextureLike> = Type extends TextureLike
         ? Omit<Partial<Type>, 'dimension'> &
             (Type['dimension'] extends '2d'
               ? { readonly dimension?: '2d' }
               : { readonly dimension: Type['dimension'] })
         : never;
       export type CreateTextureOptions = CreateTextureVariantOptions<TextureLike> & {
         readonly resource?: ImageResourceReference | null;
       };`,
      ts.ScriptTarget.Latest,
      true,
    );
    const [result] = lowerTypeScriptSources([
      { packageName: '@flighthq/types', sourceFile, upstreamDirectory: '/flight' },
    ]);
    const emitted = emitIrModuleCpp(result!.module, { runtimeProfile: 'flight-cpp' });

    // The generic DECLARATION stays erased, which is the documented contract for a conditional whose
    // check cannot be decided where it is written; the diagnostic is that contract, not a new failure.
    // Resolving it is the instantiated REFERENCE's job, and that is what changed.
    expect(result!.diagnostics.map((diagnostic) => diagnostic.message)).toEqual(['unsupported type ConditionalType']);
    // The declaration's conditional cannot be evaluated from the substitution alone: the syntactic
    // substitution replaces a parameter only where the node IS the bare reference, and the check names
    // it inside an indexed access. The instantiation is known at the reference, so the checker's answer
    // for that reference is used instead -- and the distributive outer conditional makes the branches
    // separate alternatives, which is how a union of object types is emitted everywhere else.
    expect(emitted.contents).toContain('std::variant<');
    expect(emitted.contents).not.toContain('multiple-inheritance');
  });

